package io.github.chronotask.trigger

/**
 * Source origin of a triggered task invocation.
 */
enum class TriggerSource {
    /** Triggered according to the regular schedule timeline. */
    SCHEDULE,

    /** Compensatory trigger generated by the misfire resolution mechanism. */
    MISFIRE,

    /** Manually triggered via programmatic request (e.g. triggerNow()). */
    MANUAL
}
